def _grant_permissions():
    """Donnée : ajoute les droits d'impression aux rôles existants (sans retirer ceux déjà accordés)."""
    import json
    conn = op.get_bind()
    roles = sa.table("roles", sa.column("code", sa.String), sa.column("permissions", sa.JSON))
    for code, perms in list(conn.execute(sa.select(roles.c.code, roles.c.permissions))):
        add = _GRANTS.get(code)
        if not add:
            continue
        perms = list(perms if isinstance(perms, list) else json.loads(perms or "[]"))
        merged = perms + [p for p in add if p not in perms]
        if merged != perms:
            conn.execute(roles.update().where(roles.c.code == code).values(permissions=merged))


